  }

  printSequenceExpression(printer: any, node: t.SequenceExpression) {

  printer.printList(node.expressions, node);
  }

  printThisExpression(printer: any) {

  printer.word("this");
  }

  printSuper(printer: any) {

  printer.word("super");
  }

  printisDecoratorMemberExpression(printer: any, node: t.Expression | t.V8IntrinsicIdentifier,) {

  switch (node.type) {
    case "Identifier":
      return true;
    case "MemberExpression":
      return (
        !node.computed &&
        node.property.type === "Identifier" &&
        this.printisDecoratorMemberExpression(printer, node.object)
      );
    default:
      return false;
  }
  }

  printshouldParenthesizeDecoratorExpression(printer: any, node: t.Expression | t.V8IntrinsicIdentifier,) {

  if (node.type === "CallExpression") {
    node = node.callee;
  }
  if (node.type === "ParenthesizedExpression") {
    // We didn't check extra?.parenthesized here because we don't track decorators in needsParen
