  printArrowFunctionExpression(printer: any, node: t.ArrowFunctionExpression,) {

  if (node.async) {
    printer.word("async");
    printer.space();
  }

  const firstParam = node.params[0];

  // Try to avoid printing parens in simple cases, but only if we're pretty
  // sure that they aren't needed by type annotations or potential newlines.
  if (
    !printer.format.retainLines &&
    // Auxiliary comments can introduce unexpected newlines
    !printer.format.auxiliaryCommentBefore &&
    !printer.format.auxiliaryCommentAfter &&
    node.params.length === 1 &&
    isIdentifier(firstParam) &&
    !this.printhasTypesOrComments(printer, node, firstParam)
  ) {
    printer.print(firstParam, node);
  } else {
    this.print_params(printer, node);
  }

  this.print_predicate(printer, node);

  printer.space();
  printer.token("=>");
  printer.space();

  printer.print(node.body, node);
  }

  printhasTypesOrComments(printer: any, node: t.ArrowFunctionExpression,
  param: t.Identifier,) {

  return !!(
    node.typeParameters ||
    node.returnType ||
    node.predicate ||
    param.typeAnnotation ||
    param.optional ||
    param.leadingComments?.length ||
    param.trailingComments?.length
